4	// Money moved between the owner's own accounts is a transfer, never income or spending.
5	// Detection is deterministic: IBAN evidence from the source rows, or an exact opposite
6	// amount between two own accounts that the statement itself calls a transfer. Every
7	// decision goes through the audited link RPCs, so each one can be undone.
8	
9	export const MATCH_DAYS = 3;
10	const IBAN = /^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/;
11	
12	export function normalizeIban(value: string) {
13	  const iban = value.replace(/\s/g, "").toUpperCase();
14	  return IBAN.test(iban) ? iban : null;
15	}
16	
17	/** Every IBAN-shaped value in an original source row (counterparty columns differ per bank). */
18	export function sourceIbans(row: unknown) {
19	  if (!row || typeof row !== "object") return [];
20	  return Object.values(row).flatMap(value => typeof value === "string" ? [normalizeIban(value)].filter((iban): iban is string => Boolean(iban)) : []);
21	}
22	
23	export type TransferCandidate = {
24	  id: string; version: number; accountId: string; postedOn: string; amountMinor: bigint; currencyCode: string;
25	  reviewReasons: string[]; ibans: string[];
26	};
27	export type OwnAccounts = { tracked: Map<string, string>; untracked: Map<string, string> }; // IBAN → account id / identifier id
28	
29	const days = (a: string, b: string) => Math.abs(Date.parse(a) - Date.parse(b)) / 86400000;
30	
31	export function findOwnTransfers(rows: TransferCandidate[], own: OwnAccounts) {
32	  // The posting account's own IBAN often appears in its row too; only the other side counts.
33	  const counterparts = (row: TransferCandidate) => row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
34	  const points = (row: TransferCandidate, accountId: string) => counterparts(row).some(iban => own.tracked.get(iban) === accountId);
35	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor
36	    && out.currencyCode === into.currencyCode && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= MATCH_DAYS;
37	  const used = new Set<string>();
38	  const pairs: { outId: string; inId: string }[] = [];
39	  const outs = rows.filter(row => row.amountMinor < 0n), ins = rows.filter(row => row.amountMinor > 0n);
40	  const take = (out: TransferCandidate, into: TransferCandidate) => { used.add(out.id); used.add(into.id); pairs.push({ outId: out.id, inId: into.id }); };
41	
42	  // IBAN-proven pairs first, closest date wins.
43	  for (const out of outs) {
44	    const proven = ins.filter(into => !used.has(into.id) && matches(out, into) && (points(out, into.accountId) || points(into, out.accountId)))
45	      .sort((a, b) => days(out.postedOn, a.postedOn) - days(out.postedOn, b.postedOn) || a.id.localeCompare(b.id));
46	    if (!used.has(out.id) && proven[0]) take(out, proven[0]);
47	  }
48	  // Without IBAN evidence: the statement says transfer and the match is unambiguous both ways.
49	  for (const out of outs) {
50	    if (used.has(out.id)) continue;
51	    const options = ins.filter(into => !used.has(into.id) && matches(out, into));
52	    if (options.length !== 1) continue;
53	    const into = options[0];
54	    if (outs.filter(other => !used.has(other.id) && matches(other, into)).length !== 1) continue;
55	    if (out.reviewReasons.includes("source_transfer") || into.reviewReasons.includes("source_transfer")) take(out, into);
56	  }
57	  // A leg that names an own account Moneo doesn't track.
58	  const single = rows.flatMap(row => {
59	    if (used.has(row.id)) return [];
60	    const identifierId = counterparts(row).map(iban => own.untracked.get(iban)).find(Boolean);
61	    return identifierId ? [{ transactionId: row.id, identifierId }] : [];
62	  });
63	  return { pairs, single };
64	}
